insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones, official_url) values ('land-readjustment-act', 'law'::law_kind, '土地区画整理法', 'Land Readjustment Act', null, '土地の区画を整え直し、道路や公園などを一体で整備する「土地区画整理事業」の手続きを定める法律。', null, 210, 'planning', 1954, array['land']::text[], '地権者が少しずつ土地を出し合い（減歩）、道路・公園などの公共施設と使いやすい宅地を同時につくる。', '{}'::text[], '{}'::text[], '[]'::jsonb, '[]'::jsonb, 'https://laws.e-gov.go.jp/law/329AC0000000119');
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones, official_url) values ('ancient-capitals-act', 'law'::law_kind, '古都保存法', 'Act on Special Measures for Preservation of Historic Natural Features in Ancient Cities', '古都保存法', '京都・奈良・鎌倉・飛鳥などの古都で、歴史と一体になった自然や風景（歴史的風土）を守るための法律。', null, 220, 'landscape', 1966, array['heritage','townscape']::text[], '歴史的風土保存区域を定め、とくに大事な所は特別保存地区として建築や造成を厳しく制限する。', '{}'::text[], '{}'::text[], '[]'::jsonb, '[{"year": 1980, "label": "明日香村の特別措置法"}]'::jsonb, 'https://laws.e-gov.go.jp/law/341AC1000000001');
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones, official_url) values ('port-act', 'law'::law_kind, '港湾法', 'Port and Harbor Act', null, '港の開発・利用・管理を定める法律。港の緑地を民間が整備・運営する仕組みも含む。', null, 230, 'water', 1950, array['waterfront','private']::text[], '港を整え、使い、守るための役割分担を定める。', '{}'::text[], '{}'::text[], '[]'::jsonb, '[{"year": 2022, "label": "みなと緑地PPP（港湾環境整備計画制度）"}]'::jsonb, 'https://laws.e-gov.go.jp/law/325AC0000000218');
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones, official_url) values ('local-autonomy-act', 'law'::law_kind, '地方自治法', 'Local Autonomy Act', null, '自治体の組織と運営の基本を定める法律。公の施設の管理を民間に任せる指定管理者制度の根拠。', null, 240, 'ppp', 1947, array['private']::text[], '自治体の仕事の進め方の基本を定める。', '{}'::text[], '{}'::text[], '[]'::jsonb, '[{"year": 2003, "label": "指定管理者制度"}]'::jsonb, 'https://laws.e-gov.go.jp/law/322AC0000000067');
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones, official_url) values ('road-act', 'law'::law_kind, '道路法', 'Road Act', null, '道路の種類・管理者・占用などを定める法律。歩行者のための道路空間の使い方にも関わる。', null, 250, 'road', 1952, array['walkable']::text[], '道路を整え、管理し、使うルールを定める。', '{}'::text[], '{}'::text[], '[]'::jsonb, '[{"year": 2020, "label": "歩行者利便増進道路（ほこみち）"}]'::jsonb, 'https://laws.e-gov.go.jp/law/327AC1000000180');
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones, official_url) values ('ur-agency-act', 'law'::law_kind, '独立行政法人都市再生機構法', 'Act on the Urban Renaissance Agency', 'UR法', 'UR都市機構の業務を定める法律。防災公園と周りの市街地を一体で整える事業などを担う。', null, 260, 'planning', 2003, array['disaster','land']::text[], '都市の再生と住まいの整備を担う UR の役割を定める。', '{}'::text[], '{}'::text[], '[]'::jsonb, '[]'::jsonb, 'https://laws.e-gov.go.jp/law/415AC0000000100');
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('urban-facility-decision', 'system'::law_kind, '都市施設の都市計画決定（道路・広場・公園）', 'City planning decision for urban facilities', '都市施設の決定', '道路・駅前広場・公園など、まちの骨格になる施設の位置と規模を都市計画として決める仕組み。', (select id from laws where slug = 'city-planning-act'), 270, 'planning', 1968, array['land','open-space']::text[], '将来必要になる道路や公園の場所をあらかじめ決め、建物の制限をかけて用地を守る。', array['長い時間をかけても計画どおりに整備できる']::text[], array['都市計画区域の中であること','位置・区域・規模を決める']::text[], '[{"actor": "自治体", "step": "計画案の作成・説明"}, {"actor": "住民・地権者", "step": "縦覧・意見書"}, {"actor": "審議会", "step": "都市計画審議会"}, {"actor": "自治体", "step": "都市計画決定"}, {"actor": "自治体", "step": "事業認可・整備"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('land-readjustment-project', 'system'::law_kind, '土地区画整理事業', 'Land readjustment project', null, '地権者が土地を少しずつ出し合い、道路・公園などと宅地を一体で整え直す事業。', (select id from laws where slug = 'land-readjustment-act'), 280, 'planning', 1954, array['land']::text[], 'ばらばらの土地を整えて、公共施設と使いやすい宅地を同時に生み出す。', array['用地買収によらず道路や公園をつくれる','土地の価値が上がる']::text[], array['施行地区の都市計画決定（公共施行の場合）','事業計画の認可','換地計画']::text[], '[{"actor": "自治体", "step": "施行地区の都市計画決定"}, {"actor": "事業者", "step": "事業計画の作成・認可"}, {"actor": "住民・地権者", "step": "換地計画への意見"}, {"actor": "事業者", "step": "工事・換地処分"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('urgent-renaissance-area', 'system'::law_kind, '都市再生緊急整備地域', 'Urban Renaissance Urgent Development Area', null, '都市の再生を急ぐ地域として国が指定する区域。とくに国際競争力に関わる区域は特定都市再生緊急整備地域になる。', (select id from laws where slug = 'urban-renaissance-act'), 290, 'planning', 2002, array['private']::text[], '指定された地域で、都市再生特別地区や金融・税制の支援を使えるようにする。', array['都市再生特別地区を定められる','民間都市再生事業計画の認定・支援']::text[], array['政令による地域の指定','地域整備方針']::text[], '[{"actor": "自治体", "step": "地域の指定を国に申し出"}, {"actor": "国", "step": "政令で地域を指定"}, {"actor": "国", "step": "地域整備方針の決定"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('private-urban-renaissance-plan', 'system'::law_kind, '民間都市再生事業計画の認定', 'Certified private urban renaissance project', null, '都市再生緊急整備地域の中の優良な民間プロジェクトを国が認定し、金融・税制で支える仕組み。', (select id from laws where slug = 'urban-renaissance-act'), 300, 'building', 2002, array['private','open-space']::text[], '公共施設（広場・公園・道路）の整備を伴う民間開発を後押しする。', array['金融支援・税の特例']::text[], array['都市再生緊急整備地域の中','一定規模以上で、公共施設の整備を伴う']::text[], '[{"actor": "事業者", "step": "事業計画を申請"}, {"actor": "国", "step": "国土交通大臣が認定"}, {"actor": "事業者", "step": "建設・公共施設の整備"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('park-renovation-agreement', 'system'::law_kind, '都市公園リノベーション協定', 'Urban park renovation agreement', null, 'まちなかウォーカブル区域の公園で、まちづくりに取り組む民間が公園を整え、カフェなどを置いて管理する協定の仕組み。', (select id from laws where slug = 'urban-renaissance-act'), 310, 'ppp', 2020, array['private','walkable']::text[], '駅前など歩いて楽しいまちの中心にある公園を、民間の力で生まれ変わらせる。', array['Park-PFI と同じような特例（期間・建ぺい率）','まちづくりと公園を一体で進められる']::text[], array['都市再生整備計画に定めた滞在快適性等向上区域の中','協定の締結']::text[], '[{"actor": "自治体", "step": "都市再生整備計画に区域と方針を書く"}, {"actor": "事業者", "step": "公園の整備・管理の提案"}, {"actor": "自治体", "step": "協定の締結"}, {"actor": "事業者", "step": "整備・運営"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('walkable-area', 'system'::law_kind, '滞在快適性等向上区域（まちなかウォーカブル区域）', 'Walkable district', 'ウォーカブル区域', '「居心地がよく歩きたくなる」まちなかをつくるため、都市再生整備計画に定める区域。', (select id from laws where slug = 'urban-renaissance-act'), 320, 'planning', 2020, array['walkable']::text[], '道路・公園・民間の空地をまとめて、人が滞在しやすい空間に変える。', array['公園リノベーション協定などの特例','税・予算の支援']::text[], array['都市再生整備計画への記載']::text[], '[{"actor": "自治体", "step": "都市再生整備計画に区域を定める"}, {"actor": "事業者", "step": "沿道の空間を開く・協定を結ぶ"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('redevelopment-promotion-district', 'system'::law_kind, '再開発等促進区（地区計画）', 'Redevelopment promotion district', '再開発等促進区', '工場跡地などの大きな土地の転換にあわせ、道路・広場などを整えることを条件に、容積率や用途を柔軟に決める地区計画。', (select id from laws where slug = 'city-planning-act'), 330, 'planning', 1988, array['land','open-space']::text[], 'まとまった土地を、まちに役立つ広場や通路と一体で生まれ変わらせる。', array['容積率・用途の緩和']::text[], array['地区計画の中で区域を定める','主要な公共施設の配置']::text[], '[{"actor": "事業者", "step": "計画の提案・協議"}, {"actor": "自治体", "step": "地区計画の案"}, {"actor": "審議会", "step": "都市計画審議会"}, {"actor": "自治体", "step": "都市計画決定"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('disaster-park-block', 'system'::law_kind, '防災公園街区整備事業', 'Disaster-prevention park block project', null, 'UR都市機構が、自治体の要請を受けて防災公園と周りの市街地を一体で整える事業。', (select id from laws where slug = 'ur-agency-act'), 340, 'park', null, array['disaster','green']::text[], '大きな土地を生かして、災害時の避難場所になる公園と、まちの再整備を一緒に進める。', array['用地の取得から整備までをURが担う']::text[], array['自治体の要請','防災公園としての機能（避難・備蓄など）']::text[], '[{"actor": "自治体", "step": "URに整備を要請"}, {"actor": "事業者", "step": "UR が用地取得・公園整備"}, {"actor": "自治体", "step": "公園の譲り受け・管理"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('national-government-park', 'system'::law_kind, '国営公園', 'National government park', null, '国が設置・管理する都市公園。広い地域から人が訪れる公園や、国家的な記念事業・文化的資産を生かす公園がある。', (select id from laws where slug = 'urban-parks-act'), 350, 'park', 1976, array['heritage','green']::text[], '国として守り伝えるべき自然や歴史を、公園として整える。', array['国の予算で広い範囲を整備できる']::text[], array['閣議決定などにもとづく設置']::text[], '[{"actor": "国", "step": "閣議決定・基本計画"}, {"actor": "国", "step": "用地取得・整備"}, {"actor": "国", "step": "開園・管理"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('historic-climate-zone', 'system'::law_kind, '歴史的風土特別保存地区', 'Special preservation district of historic natural features', null, '古都の歴史的風土のうち、とくに大事な区域で建築や造成などを許可制にして守る地区。', (select id from laws where slug = 'ancient-capitals-act'), 360, 'landscape', 1966, array['heritage','townscape']::text[], '遺跡や社寺と一体になった山・田畑などの風景を、そのまま残す。', array['土地の買い入れの申し出ができる']::text[], array['歴史的風土保存区域の中で都市計画として指定']::text[], '[{"actor": "国", "step": "保存区域の指定"}, {"actor": "自治体", "step": "特別保存地区の都市計画決定"}, {"actor": "住民・地権者", "step": "行為の許可申請"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('historic-site', 'system'::law_kind, '史跡・特別史跡の指定', 'Designation of historic sites', '史跡', '遺跡などを国が史跡（とくに価値の高いものは特別史跡）に指定し、現状を変える行為を許可制にする仕組み。', (select id from laws where slug = 'cultural-properties-act'), 370, 'landscape', 1950, array['heritage']::text[], '遺跡を守りながら、公園などとして公開・活用する。', array['保存・整備への補助']::text[], array['現状変更には文化庁長官の許可']::text[], '[{"actor": "国", "step": "文部科学大臣が指定"}, {"actor": "自治体", "step": "保存活用計画・整備"}, {"actor": "自治体", "step": "公開・活用"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('minato-green-ppp', 'system'::law_kind, 'みなと緑地PPP（港湾環境整備計画制度）', 'Port green space PPP', 'みなと緑地PPP', '港の緑地にカフェなどの収益施設をつくり、その収益で緑地の整備や管理もする民間事業者に、緑地を貸し付ける認定制度。', (select id from laws where slug = 'port-act'), 380, 'ppp', 2022, array['waterfront','private']::text[], '港の緑地を、民間の力でにぎわう場所に変える。', array['行政財産の緑地を長期で借りられる（最長30年）','都市公園ではできない貸し付けができる']::text[], array['港湾環境整備計画の作成','港湾管理者の認定','収益の一部を緑地に還元']::text[], '[{"actor": "自治体", "step": "港湾管理者が公募"}, {"actor": "事業者", "step": "港湾環境整備計画を提出"}, {"actor": "自治体", "step": "計画を認定・緑地を貸し付け"}, {"actor": "事業者", "step": "整備・運営"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('designated-manager', 'system'::law_kind, '指定管理者制度', 'Designated manager system', null, '公園などの公の施設の管理を、自治体が指定した民間事業者やNPOなどに任せる制度。', (select id from laws where slug = 'local-autonomy-act'), 390, 'ppp', 2003, array['private']::text[], '民間の運営ノウハウで、施設のサービスと使い勝手を高める。', array['運営の工夫で利用者サービスが上がる','管理コストの見直し']::text[], array['条例で手続きを定める','議会の議決で指定','期間を定める（多くは3〜5年）']::text[], '[{"actor": "自治体", "step": "募集・選定"}, {"actor": "審議会", "step": "議会の議決"}, {"actor": "事業者", "step": "管理・運営"}, {"actor": "自治体", "step": "モニタリング・評価"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('park-facility-permit', 'system'::law_kind, '公園施設の設置管理許可', 'Permit to install and manage park facilities', '設置管理許可', '公園管理者以外の者が、許可を受けて公園内に売店・レストランなどの公園施設を設け、管理する仕組み。', (select id from laws where slug = 'urban-parks-act'), 400, 'ppp', 1956, array['private']::text[], '公園の魅力を高める施設を、民間などが設置・運営できるようにする。', array['自治体が施設を持たなくてよい']::text[], array['公園管理者の許可（期間は最長10年）','公園の機能を損なわないこと']::text[], '[{"actor": "事業者", "step": "設置・管理の申請"}, {"actor": "自治体", "step": "許可"}, {"actor": "事業者", "step": "設置・運営・使用料の支払い"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('pedestrian-convenience-road', 'system'::law_kind, '歩行者利便増進道路（ほこみち）', 'Pedestrian convenience road', 'ほこみち', '歩道などにカフェのテラスやベンチを置きやすくするため、道路管理者が指定する道路。', (select id from laws where slug = 'road-act'), 410, 'road', 2020, array['walkable','private']::text[], '道路を、通るだけでなく滞在して楽しめる場所にする。', array['占用の基準がゆるみ、公募で最長20年の占用ができる']::text[], array['道路管理者による指定','利便増進誘導区域の設定']::text[], '[{"actor": "自治体", "step": "道路の指定・区域の設定"}, {"actor": "事業者", "step": "公募に応じて占用を申請"}, {"actor": "自治体", "step": "占用者の選定・許可"}, {"actor": "事業者", "step": "テラスなどの運営"}]'::jsonb, '[]'::jsonb);
insert into laws (slug, kind, name_ja, name_en, short_ja, summary_ja, basis_id, sort_order, topic, enacted_year, purposes, purpose_ja, merits_ja, requirements_ja, flow, milestones) values ('use-district', 'system'::law_kind, '用途地域', 'Use districts', null, '住宅地・商業地・工業地など、建てられる建物の用途や容積率・建ぺい率を地域ごとに決める仕組み（13種類）。', (select id from laws where slug = 'city-planning-act'), 420, 'planning', 1919, array['land','townscape']::text[], '用途の混ざりすぎを防ぎ、地域に合った建物の大きさに揃える。', array['まちの土地利用の基本の枠組みになる']::text[], array['都市計画区域の中で都市計画として決定']::text[], '[{"actor": "自治体", "step": "案の作成"}, {"actor": "審議会", "step": "都市計画審議会"}, {"actor": "自治体", "step": "都市計画決定"}]'::jsonb, '[]'::jsonb);
