insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'decision', null, 'うめきた2期中央地区（約12ha）を都市再生特別地区に定め、北地区・南地区ごとに建物の高さの上限を決めた。', 'https://www.city.osaka.lg.jp/toshikeikaku/cmsfiles/contents/0000499/499483/umekita2ki_toshisaiseitokubetsutiku_keikakusyo.pdf', 1 from projects p, laws l where p.slug = 'grand-green-osaka' and l.slug = 'urban-renaissance-district' on conflict (project_id, law_id) do nothing;
