insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'system', null, '大阪市とUR都市機構が防災公園街区整備事業で、地区中央に約4.5haの都市公園（うめきた公園）を整備。開発事業者がデザイン提案で上乗せの整備を行い、大阪市に引き継ぐ。', 'https://www.pref.osaka.lg.jp/o140030/daitoshimachi/umekita2ki/index.html', 3 from projects p, laws l where p.slug = 'grand-green-osaka' and l.slug = 'disaster-park-block' on conflict (project_id, law_id) do nothing;
insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'system', null, '公園の一部と基盤は土地区画整理事業で整備。', 'https://www.pref.osaka.lg.jp/o140030/daitoshimachi/umekita2ki/index.html', 4 from projects p, laws l where p.slug = 'grand-green-osaka' and l.slug = 'land-readjustment-project' on conflict (project_id, law_id) do nothing;
insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'decision', null, 'うめきた先行開発区域の都市施設として、都市計画交通広場1号「大阪北口広場」を都市計画決定。', 'https://www.city.osaka.lg.jp/osakatokei/cmsfiles/contents/0000561/561439/keii.pdf', 5 from projects p, laws l where p.slug = 'umekita-hiroba' and l.slug = 'urban-facility-decision' on conflict (project_id, law_id) do nothing;
