insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'system', 2023, '2023年3月に尼崎市と阪神電気鉄道などが協定を結び、芝生広場や飲食店を整備。関西で初めてこの制度を使った公園整備。', 'https://www.city.amagasaki.hyogo.jp/_res/projects/default_project/_page_/001/033/893/230406-01.pdf', 13 from projects p, laws l where p.slug = 'amagasaki-ekimae-chuo-park' and l.slug = 'park-renovation-agreement' on conflict (project_id, law_id) do nothing;
insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'zone', null, '協定を使える区域は、都市再生整備計画に定めたまちなかウォーカブル区域に限られる。', 'https://www.smtri.jp/report_column/report/pdf/report_20240329.pdf', 14 from projects p, laws l where p.slug = 'amagasaki-ekimae-chuo-park' and l.slug = 'walkable-area' on conflict (project_id, law_id) do nothing;
