insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'system', null, 'UR都市機構が高槻市の要請を受け、京都大学農場の跡地で防災公園と周辺市街地の改善を一体で進めた。', 'https://www.ur-net.go.jp/west/news/lrmhph000000tupr-att/ur2019_press_amaiseki-park.pdf', 17 from projects p, laws l where p.slug = 'ama-iseki-park' and l.slug = 'disaster-park-block' on conflict (project_id, law_id) do nothing;
insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'zone', null, '公園の中心は国史跡・安満遺跡。遺構を守りながら公園として活用している。', 'https://www.ur-net.go.jp/aboutus/press/hndcds000000baru-att/ur2022_press_1102_toshikouen.pdf', 18 from projects p, laws l where p.slug = 'ama-iseki-park' and l.slug = 'historic-site' on conflict (project_id, law_id) do nothing;
