insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'decision', 2012, '4車線を2車線にして歩道を広げる内容で、2012年1月に都市計画決定。その前の2010年度に交通社会実験を行った。', 'https://www.city.kyoto.lg.jp/tokei/cmsfiles/contents/0000249/249760/05.pdf', 21 from projects p, laws l where p.slug = 'shijo-dori' and l.slug = 'urban-facility-decision' on conflict (project_id, law_id) do nothing;
insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'system', 2009, '再整備にあわせ、2009年に公園内のサービス施設・レストランを整備・運営する民間事業者を募集。', 'https://www.city.osaka.lg.jp/contents/wdu210/mayor/img/090514.pdf', 22 from projects p, laws l where p.slug = 'nakanoshima-park' and l.slug = 'park-facility-permit' on conflict (project_id, law_id) do nothing;
