insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'decision', 1996, '大阪球場跡地を含む難波地区の再開発を1996年に都市計画決定。難波地区地区計画（約12.7ha）は全域が再開発等促進区。', 'https://www.city.osaka.lg.jp/toshikeikaku/cmsfiles/contents/0000650/650809/s08_namba_k.pdf', 24 from projects p, laws l where p.slug = 'namba-parks' and l.slug = 'redevelopment-promotion-district' on conflict (project_id, law_id) do nothing;
insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'system', 2013, '2013年3月に国が民間都市再生事業計画として認定。敷地内に豊かな緑地をつくり、周りの公園も整備することを目的に掲げた（広場約3,400㎡・公園約1,500㎡）。', 'https://www.mlit.go.jp/common/000991173.pdf', 25 from projects p, laws l where p.slug = 'shin-daibiru-dojima-no-mori' and l.slug = 'private-urban-renaissance-plan' on conflict (project_id, law_id) do nothing;
