insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'decision', null, '堂島浜一丁目地区（約0.5ha）を都市再生特別地区に追加。中之島公園（堂島公園）を中心とした水辺のにぎわい拠点づくりを目的に掲げた（2020年の計画書案）。', 'https://www.city.osaka.lg.jp/toshikeikaku/cmsfiles/contents/0000499/499483/doujimahama_toshisaiseitokubetsutiku_keikakusyo.pdf', 27 from projects p, laws l where p.slug = 'k-10cdb688' and l.slug = 'urban-renaissance-district' on conflict (project_id, law_id) do nothing;
insert into project_laws (project_id, law_id, role, decided_year, note_ja, source_url, sort_order) select p.id, l.id, 'zone', null, '中之島・御堂筋周辺地域の都市再生緊急整備地域の中。', 'https://www.city.osaka.lg.jp/toshikeikaku/cmsfiles/contents/0000499/499483/doujimahama_toshisaiseitokubetsutiku_keikakusyo.pdf', 28 from projects p, laws l where p.slug = 'k-10cdb688' and l.slug = 'urgent-renaissance-area' on conflict (project_id, law_id) do nothing;
insert into papers (slug, kind, title, authors, year, venue, volume, issue, pages, doi, url, language, summary_ja, review_status) values ('ishibashi-2021-public-open-space', 'article'::paper_kind, '総合設計制度における公共貢献としての公開空地整備のあり方に関する研究', '石橋 大輝, 村木 美貴, 須永 大介', 2021, '都市計画論文集', '56', '3', '1245-1252', '10.11361/journalcpij.56.1245', null, 'ja', '東京都心部では総合設計制度が最も多く公開空地を生んでいる一方、容積率の緩和が大きい歩道状の空地が多いことを課題として示した。地域の特性に合った公開空地を評価する緩和の仕組みと、事業として成り立つ費用分担のあり方を提案している。', 'draft');
insert into paper_laws (paper_id, law_id) select p.id, l.id from papers p, laws l where p.slug = 'ishibashi-2021-public-open-space' and l.slug = 'comprehensive-design';
insert into papers (slug, kind, title, authors, year, venue, volume, issue, pages, doi, url, language, summary_ja, review_status) values ('tsukada-2021-park-cafe', 'article'::paper_kind, '敷島公園を事例とした収益施設（カフェ）の利用意向とイメージ分析に関する研究', '塚田 伸也, 森田 哲夫', 2021, 'ランドスケープ研究', '84', '5', '615-620', '10.5632/jila.84.615', null, 'ja', '指定管理者制度と Park-PFI でカフェが整備された前橋市の敷島公園で、利用者の意向と評価をウェブアンケートで調べた。約6割がカフェを使いたいと答え、公園の魅力が上がるという声とともに、駐車場の混雑やごみの増加を心配する声もあった。', 'draft');
