insert into papers (slug, kind, title, authors, year, venue, volume, issue, pages, doi, url, language, summary_ja, review_status) values ('isono-2020-urban-renaissance-culture', 'article'::paper_kind, '都心部における企業の文化貢献に関する研究 ―東京都の都市再生特別地区を対象として―', '礒野 小梅, 豊川 斎赫', 2020, '日本建築学会計画系論文集', '85', '778', '2641-2649', '10.3130/aija.85.2641', null, 'ja', '東京都の都市再生特別地区で提案された文化面の公共貢献を、当初の計画と完成後の運営へのヒアリングから評価した。提案は多様になった一方、文化施設とは言いにくいものも貢献と評価されており、容積の緩和以外の支援も含めた制度の見直しが課題だと指摘している。', 'draft');
