insert into papers (slug, kind, title, authors, year, venue, volume, issue, pages, doi, url, language, summary_ja, review_status) values ('fukasawa-2023-river-space', 'report'::paper_kind, '河川空間活用事例調査研究（中間報告）', '深沢 瞳, 多田 智和, 酒井 聡佑, 兼元 雄基, 田中 和氏', 2023, '国土交通政策研究所紀要', '81', null, null, null, 'https://www.mlit.go.jp/pri/kikanshi/pdf/2023/81_6.pdf', 'ja', '河川空間のオープン化の取り組みは、人口が多い都市部と少ない郊外部で多いことを示した。増水時のイベント中止の基準づくりや、岡崎市・島田市で河川・道路・公園を一体で使う体制と担い手づくりの工夫を報告している。', 'draft');
insert into paper_laws (paper_id, law_id) select p.id, l.id from papers p, laws l where p.slug = 'fukasawa-2023-river-space' and l.slug = 'river-space-use';
