-- RULE タブ: 制度カード（目的・メリット・要件・手続きの流れ・年表）、制度どうしの関係、事例との関係の種類、論文とのつながり
alter table laws
  add column topic text check (topic in ('planning', 'park', 'landscape', 'building', 'water', 'road', 'ppp')),
  add column enacted_year smallint check (enacted_year between 1800 and 2100),
  add column purposes text[] not null default '{}',
  add column purpose_ja text,
  add column merits_ja text[] not null default '{}',
  add column requirements_ja text[] not null default '{}',
  add column flow jsonb not null default '[]',        -- [{actor, step}] 手続きのおおまかな流れ
  add column milestones jsonb not null default '[]';  -- [{year, label}] 創設・改正

create table law_links (
  from_law_id uuid not null references laws (id) on delete cascade,
  to_law_id uuid not null references laws (id) on delete cascade,
  note_ja text,
  primary key (from_law_id, to_law_id)
);
alter table law_links enable row level security;
create policy law_links_public_read on law_links for select using (true);
create policy law_links_admin on law_links for all using (is_admin()) with check (is_admin());

-- 事例との関係の種類: system 制度を使った / decision 都市計画決定・事業認可 / zone 区域・地域の指定
alter table project_laws
  add column role text not null default 'system' check (role in ('system', 'decision', 'zone')),
  add column decided_year smallint check (decided_year between 1800 and 2100);

create table paper_laws (
  paper_id uuid not null references papers (id) on delete cascade,
  law_id uuid not null references laws (id) on delete cascade,
  primary key (paper_id, law_id)
);
alter table paper_laws enable row level security;
create policy paper_laws_public_read on paper_laws for select using (true);
create policy paper_laws_admin on paper_laws for all using (is_admin()) with check (is_admin());

-- 条例の分野
update laws set topic = 'landscape' where slug in ('osaka-city-landscape', 'kyoto-city-townscape', 'kobe-city-landscape');
update laws set topic = 'park' where slug in ('osaka-pref-nature-conservation', 'hyogo-environment');

