update laws set topic = 'water', enacted_year = 1964, purposes = array['waterfront']::text[], purpose_ja = '川を洪水から守り、水を利用し、川の環境を保つための法律。', merits_ja = '{}'::text[], requirements_ja = '{}'::text[], flow = '[]'::jsonb, milestones = '[{"year": 1896, "label": "旧河川法"}, {"year": 1997, "label": "目的に「河川環境」を追加"}, {"year": 2011, "label": "河川敷地占用許可準則の改正（オープン化）"}]'::jsonb, official_url = 'https://laws.e-gov.go.jp/law/339AC0000000167' where slug = 'river-act';
