update laws set topic = 'building', enacted_year = 2006, purposes = array['walkable']::text[], purpose_ja = '高齢者や障害のある人が移動しやすいよう、施設の基準を定める法律。', merits_ja = '{}'::text[], requirements_ja = '{}'::text[], flow = '[]'::jsonb, milestones = '[]'::jsonb, official_url = 'https://laws.e-gov.go.jp/law/418AC0000000091' where slug = 'barrier-free-act';
update laws set topic = 'building', enacted_year = 1970, purposes = array['open-space','private']::text[], purpose_ja = '敷地の中に誰でも入れる空地をつくることと引き換えに、建物の容積率や高さの制限をゆるめる。', merits_ja = array['容積率・高さの上限が上がる','まちに歩行者のための広場や通路が増える']::text[], requirements_ja = array['一定以上の敷地面積','公開空地の面積・幅・配置などの基準（自治体ごとに許可基準がある）','公開空地をいつでも通れる・使える状態に保つ']::text[], flow = '[{"actor": "事業者", "step": "事前相談・計画づくり"}, {"actor": "自治体", "step": "許可基準に照らして協議"}, {"actor": "審議会", "step": "建築審査会の同意"}, {"actor": "自治体", "step": "特定行政庁が許可"}, {"actor": "事業者", "step": "建設・公開空地の維持管理"}]'::jsonb, milestones = '[]'::jsonb where slug = 'comprehensive-design';
update laws set topic = 'planning', enacted_year = 1980, purposes = array['townscape','open-space']::text[], purpose_ja = '地区の特性に合わせて、道や広場の配置、建物の用途・高さ・壁面の位置などを細かく決める。', merits_ja = array['地区ごとのまちなみのルールをつくれる','再開発等促進区などと組み合わせて土地の使い方を柔軟にできる']::text[], requirements_ja = array['地区の目標と整備の方針を定める','必要に応じて地区整備計画で具体的なルールを定める']::text[], flow = '[{"actor": "住民・地権者", "step": "勉強会・案の検討"}, {"actor": "自治体", "step": "原案の作成・説明会"}, {"actor": "住民・地権者", "step": "意見書の提出"}, {"actor": "審議会", "step": "都市計画審議会"}, {"actor": "自治体", "step": "都市計画決定・告示"}]'::jsonb, milestones = '[]'::jsonb where slug = 'district-plan';
update laws set topic = 'park', enacted_year = 2004, purposes = array['green']::text[], purpose_ja = '緑の少ない市街地で、一定規模以上の建物を建てるときに敷地の緑化を義務にする。', merits_ja = array['建て替えのたびに緑が確実に増える']::text[], requirements_ja = array['用途地域内で区域を都市計画で指定','緑化率の最低限度を定める']::text[], flow = '[{"actor": "自治体", "step": "区域と緑化率を都市計画で決定"}, {"actor": "事業者", "step": "建築確認と合わせて緑化計画を出す"}, {"actor": "自治体", "step": "完了時に緑化を確認"}]'::jsonb, milestones = '[]'::jsonb where slug = 'greening-district';
update laws set topic = 'ppp', enacted_year = 2017, purposes = array['private','green']::text[], purpose_ja = '公園にカフェなどの収益施設を置く民間事業者を公募で選び、その収益で園路や広場も一緒に整えてもらう。', merits_ja = array['設置管理許可の期間が最長20年に延びる','建ぺい率の上乗せ（+10%）','自転車駐車場・看板などの占用ができる','自治体は整備費を抑えられる']::text[], requirements_ja = array['公募設置等指針の作成と公募','収益の一部を公園の整備（特定公園施設）に還元する','公募設置等計画の認定']::text[], flow = '[{"actor": "自治体", "step": "公募設置等指針をつくり公募"}, {"actor": "事業者", "step": "公募設置等計画を提出"}, {"actor": "自治体", "step": "審査・選定・計画の認定"}, {"actor": "事業者", "step": "収益施設と園路・広場の整備"}, {"actor": "自治体", "step": "特定公園施設の引き渡し"}, {"actor": "事業者", "step": "運営（最長20年）"}]'::jsonb, milestones = '[]'::jsonb where slug = 'park-pfi';
update laws set topic = 'park', enacted_year = 2017, purposes = array['green','private']::text[], purpose_ja = '民間が持つ空き地などを、住民が使える緑地として整備・公開する計画を自治体が認定する。', merits_ja = array['固定資産税の軽減','整備費の支援']::text[], requirements_ja = array['一定以上の面積','5年以上の公開']::text[], flow = '[{"actor": "事業者", "step": "市民緑地設置管理計画をつくる"}, {"actor": "自治体", "step": "計画を認定"}, {"actor": "事業者", "step": "整備・公開・管理"}]'::jsonb, milestones = '[]'::jsonb where slug = 'citizen-green-space';
update laws set topic = 'planning', enacted_year = 2002, purposes = array['private','open-space']::text[], purpose_ja = '都市再生緊急整備地域の中で、既存の用途地域などのルールにとらわれない自由な計画を、都市への貢献と引き換えに認める。', merits_ja = array['容積率・用途・高さを白紙から決められる','事業者から都市計画を提案できる']::text[], requirements_ja = array['都市再生緊急整備地域の中にあること','広場・緑地・歩行者ネットワーク・防災などの公共貢献']::text[], flow = '[{"actor": "事業者", "step": "都市計画の提案"}, {"actor": "自治体", "step": "公共貢献の評価と協議"}, {"actor": "審議会", "step": "都市計画審議会"}, {"actor": "自治体", "step": "都市計画決定（原則6か月以内に判断）"}, {"actor": "事業者", "step": "建設・公共貢献の整備"}]'::jsonb, milestones = '[]'::jsonb where slug = 'urban-renaissance-district';
update laws set topic = 'water', enacted_year = 2011, purposes = array['waterfront','private']::text[], purpose_ja = '地域の合意があれば、河川敷にカフェやイベント施設などを民間事業者が置けるようにする。', merits_ja = array['水辺ににぎわいの場をつくれる','占用期間は最長10年（2016年から）']::text[], requirements_ja = array['協議会などでの地域の合意','河川管理者による区域・施設・占用主体の指定','治水上の支障がないこと']::text[], flow = '[{"actor": "自治体", "step": "協議会で地域の合意をつくる"}, {"actor": "国", "step": "河川管理者が区域・施設・主体を指定"}, {"actor": "事業者", "step": "占用許可の申請"}, {"actor": "国", "step": "占用許可"}, {"actor": "事業者", "step": "営業・水辺の管理"}]'::jsonb, milestones = '[]'::jsonb where slug = 'river-space-use';
